package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.GoalType;
import org.apache.commons.math3.optim.univariate.UnivariateRealOptimizer;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.apache.commons.math3.random.RandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getResult_TriageGen3Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = new JDKRandomGenerator();
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 10, mockGenerator);
    }

    /**
     * Tests getResult() when the underlying optimizer returns a specific value.
     * This covers the primary functional path and line coverage.
     */
    @Test
    public void testGetResultReturnsValueFromOptimizer() throws Exception {
        double expectedResult = 42.0;

        // We must trigger the optimization process or ensure the internal optimizer state is set.
        // Since getResult() simply delegates to optimizer.getResult(), 
        // we mock the behavior of the internal optimizer.
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        double actualResult = multiStartOptimizer.getResult();

        assertEquals("The result returned by getResult should match the underlying optimizer's result.", 
                     expectedResult, actualResult, 1e-15);
    }

    /**
     * Tests getResult() when the underlying optimizer returns a negative value.
     */
    @Test
    public void testGetResultReturnsNegativeValue() {
        double expectedResult = -123.456;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        double actualResult = multiStartOptimizer.getResult();

        assertEquals("The result should correctly return negative values from the underlying optimizer.", 
                     expectedResult, actualResult, 1e-15);
    }

    /**
     * Tests getResult() when the underlying optimizer returns zero.
     */
    @Test
    public void testGetResultReturnsZero() {
        double expectedResult = 0.0;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        double actualResult = multiStartOptimizer.getResult();

        assertEquals("The result should correctly return zero.", 
                     expectedResult, actualResult, 1e-15);
    }

    /**
     * Tests getResult() when the underlying optimizer throws an exception.
     * This ensures that the exception propagates correctly (line coverage for exception propagation).
     */
    @Test(expected = RuntimeException.class)
    public void testGetResultPropagatesException() {
        when(mockOptimizer.getResult()).thenThrow(new RuntimeException("Optimization failed"));

        multiStartOptimizer.getResult();
    }
}
